**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();
    int k = 4;

    // Suma pierwszego okna
    int suma = 0;
    for (int i = 0; i < k; i++) suma += T[i];

    double maxSr = (double)suma / k, minSr = (double)suma / k;
    int maxPos = 0, minPos = 0;

    for (int i = 1; i <= n - k; i++) {
        suma = suma - T[i - 1] + T[i + k - 1];
        double sr = (double)suma / k;
        if (sr > maxSr) { maxSr = sr; maxPos = i; }
        if (sr < minSr) { minSr = sr; minPos = i; }
    }

    cout << "a) Okno o max sredniej:" << endl;
    cout << "   Pozycja: " << maxPos + 1 << ", elementy:";
    for (int i = maxPos; i < maxPos + k; i++) cout << " " << T[i];
    cout << endl;
    cout << "   Srednia: " << fixed << setprecision(2) << maxSr << endl;

    cout << endl << "b) Okno o min sredniej:" << endl;
    cout << "   Pozycja: " << minPos + 1 << ", elementy:";
    for (int i = minPos; i < minPos + k; i++) cout << " " << T[i];
    cout << endl;
    cout << "   Srednia: " << fixed << setprecision(2) << minSr << endl;
    return 0;
}
```

**Wyjasnienie**: Technika przesuwnego okna (sliding window). Zamiast liczyc sume od nowa dla kazdego okna, aktualizujemy ja: odejmujemy element wychodzacy, dodajemy wchodzacy. Zlozonosc O(n).

